	/** 
	 * jumpstart the process by instantiating2 Dashboard
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		dashboardId = DashboardService.getDashboardInstance()
		.createDashboard( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		DashboardService.getDashboardInstance()
				.createDashboard( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.dashboardSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Dashboard : " + successValue.getDashboardId());
							  if (successValue.getDashboardId().equals(dashboardId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfDashboardList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Dashboard test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dashboard consumed")
					);
			subscriber.dashboardSubscribe( dashboardId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Dashboard : " + successValue.getDashboardId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfDashboardList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on dashboard for dashboardId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Dashboard. 
	 */
	protected Dashboard read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Dashboard" );

		Dashboard entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Dashboard with primary key" );
		msg.append( dashboardId );
		
		DashboardFetchOneSummary fetchOneSummary = new DashboardFetchOneSummary( dashboardId );

		try {
			entity = DashboardService.getDashboardInstance().getDashboard( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Dashboard " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Dashboard.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Dashboard." );

		StringBuilder msg = new StringBuilder( "Failed to update a Dashboard : " );        
		Dashboard entity = read();
		UpdateDashboardCommand command = generateUpdateCommand();
		command.setDashboardId(entity.getDashboardId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Dashboard." );

			// for use later on...
			dashboardId = entity.getDashboardId();

			DashboardService proxy = DashboardService.getDashboardInstance();  

			proxy.updateDashboard( command ).get();

			LOGGER.info( "-- Successfully saved Dashboard - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + dashboardId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Dashboard.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Dashboard." );

		Dashboard entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Dashboard with id " + dashboardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Dashboard with id " + dashboardId );

			throw e;
		}

		try{
			DashboardService.getDashboardInstance().delete( new DeleteDashboardCommand( entity.getDashboardId() ) ).get();
			LOGGER.info( "-- Successfully deleted Dashboard with id " + dashboardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Dashboard with id " + dashboardId );

			throw e;
		}
	}

	/**
	 * get all Dashboards.
	 */
	protected List<Dashboard> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Dashboards:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Dashboard : " );        
		List<Dashboard> collection  = new ArrayList<>();

		try {
			// call the static get method on the DashboardService
			collection = DashboardService.getDashboardInstance().getAllDashboard();
			assertNotNull( collection, "An Empty collection of Dashboard was incorrectly returned.");
			
			// Now print out the values
			Dashboard entity = null;            
			Iterator<Dashboard> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDashboardId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

